 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    # Objects are monochromatic 4-connected components.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            min_r = min(y for y, _ in cells)
            max_r = max(y for y, _ in cells)
            min_c = min(x for _, x in cells)
            max_c = max(x for _, x in cells)
            occupied = set(cells)
            perimeter = {
                (y, x)
                for y in range(min_r, max_r + 1)
                for x in range(min_c, max_c + 1)
                if y in (min_r, max_r) or x in (min_c, max_c)
            }
            is_frame = perimeter <= occupied
            objects.append({"color": color, "cells": cells,
                            "frame": is_frame,
                            "min_r": min_r, "max_r": max_r})

    placed = []
    # Hollow rectangular outlines move upward, maintaining their order.
    frames = sorted((o for o in objects if o["frame"]),
                    key=lambda o: (o["min_r"], min(c for _, c in o["cells"])))
    for obj in frames:
        shift = 0
        while True:
            candidate = {(r + shift - 1, c) for r, c in obj["cells"]}
            if any(r < 0 for r, _ in candidate):
                break
            if any(candidate & other for other in placed):
                break
            shift -= 1
        moved = {(r + shift, c) for r, c in obj["cells"]}
        placed.append(moved)
        obj["moved"] = moved

    # All other motifs move downward, stacking against one another.
    placed_down = []
    motifs = sorted((o for o in objects if not o["frame"]),
                    key=lambda o: (-o["max_r"], -max(c for _, c in o["cells"])))
    for obj in motifs:
        shift = 0
        while True:
            candidate = {(r + shift + 1, c) for r, c in obj["cells"]}
            if any(r >= h for r, _ in candidate):
                break
            if any(candidate & other for other in placed_down):
                break
            shift += 1
        moved = {(r + shift, c) for r, c in obj["cells"]}
        placed_down.append(moved)
        obj["moved"] = moved

    out = [[0] * w for _ in range(h)]
    for obj in objects:
        for r, c in obj["moved"]:
            out[r][c] = obj["color"]
    return out
